mapper.select:
SELECT a.id, a.vehicle_id, v.vin, a.stage_status, a.allocated_date, a.dealer_id, d.dealer_name, a.sales_status, a.remark3, a.confirmed_by, a.confirmed_at FROM t_veh_allocation a INNER JOIN t_vehicle v ON v.id = a.vehicle_id AND v.deleted = 0 LEFT JOIN t_md_dealer d ON d.id = a.dealer_id AND d.deleted = 0 WHERE a.deleted = 0
AND v.vin LIKE CONCAT('%', #{query.vin}, '%')
AND a.dealer_id = #{query.dealerId}
AND a.stage_status = #{query.stageStatus}
ORDER BY a.id DESC
